// function formatPrice(num) mein number do
// Agar number nahi: "₹0.00"
// Agar negative: "₹0.00"
// Warna "₹{num.toFixed(2)}"

solution:
function formatPrice(num) {
  if (typeof num !== "number" || Number.isNaN(num)) return "₹0.00"
  if (num < 0) return "₹0.00"
  return `₹${num.toFixed(2)}`
}
